class Solution(object):
    def reversePrefix(self, word, ch):
        """
        :type word: str
        :type ch: str
        :rtype: str
        """
        ind = word.find(ch)
        if ind == -1:
            return word
        else:
            return word[:ind + 1][::-1] + word[ind + 1:]
